 */
@Configuration
@Profile({"dev", "test"})
public class IdentityProvidersConfig {

    @Bean
    public FaceIdentityResolver faceIdentityResolver(
            @Value("${app.identity.namespace:mvp-local}") String namespace) {
        return new DevTestFaceIdentityResolver(namespace);
    }
}

